        View.setMenuSelection(index);
      };
      item.addEventListener("focus", selectItem);
      item.addEventListener("mouseenter", selectItem);
    });
  },

  bindHistory() {
    window.addEventListener("popstate", () => {
      if (this.redirectIfUnknownRoute()) return;
