    const bios = document.querySelector("#bios-boot-screen");
    if (!bios) return;
    const dismiss = () => {
      bios.classList.add("is-hidden");
      document.removeEventListener("keydown", handleDismiss);
      bios.removeEventListener("click", handleDismiss);
