      this._typingTimers.forEach(timer => window.clearInterval(timer));
    }
    this._typingTimers = [];

    const elementsToType = screenEl.querySelectorAll('h2[data-i18n], .quote span[data-i18n]');

    elementsToType.forEach(el => {
