      const tempDiv = document.createElement("div");
      tempDiv.innerHTML = fullHtml;
      const plainText = tempDiv.textContent || fullHtml;

      el.textContent = "";
      let i = 0;
      const timer = window.setInterval(() => {
        if (i < plainText.length) {
          el.textContent += plainText.charAt(i);
